INSERT INTO `metric_templates` VALUES ('443f18a6-3b6c-4fc4-940f-4d9f0a9bd9e8','Cybersecurity Incident Summary Sections','Verifies cybersecurity incident summary contains Summary, Findings and Recommendations sections.','section_check','{\"required_sections\":[\"Summary\",\"Findings\",\"Recommendations\"]}','{\"all_present\":true}',1,1,'2026-03-10 10:53:33.507307','2026-03-10 11:43:47.000000'),('4600ef74-d48f-401c-8af5-18e701e16fb3','CS Incident keyword checks','Verifies keyword content of the CS incident summary report.','keyword_check','{\"keywords\":[\"users\",\"findings\",\"recommendations\"],\"min_count\":1,\"case_sensitive\":false,\"use_word_boundary\":false}','{\"min_matches\":1}',1,1,'2026-03-11 09:17:00.652992','2026-03-11 09:17:00.652992'),('a70085f4-6510-4fb9-8991-b9d9e336eff9','CS Incident Date Check','Checks when the date of submission of the CS incident summary report.','date_check','{\"submission_frequency\":\"monthly\",\"submission_month\":12,\"deadline_day\":5,\"deadline_month_offset\":1,\"max_days_late\":15,\"custom_period_regex\":\"^(\\\\d{4})(\\\\d{2})$\",\"custom_period_year_group\":1,\"custom_period_month_group\":2,\"custom_period_fallback_month\":12}','{\"within_deadline\":true}',1,1,'2026-03-11 09:15:53.467665','2026-03-11 09:15:53.467665'),('b52ce287-707c-493c-9ef8-8ac3ca5d2352','Cybersecurity Incident Summary Metrics','Summary counts of the incidents of the cybersecurity incident summary report.','property_check','{\"mode\":\"number_extraction\",\"field\":\"extracted_text\",\"keywords\":[\"total incidents\",\"resolved incidents\",\"open incidents\",\"users trained\"],\"keyword\":\"total incidents\",\"comparison\":\"gte\",\"expected_number\":1,\"expected_numbers\":[1,1,0,10],\"window_chars\":120}','{\"matches_pattern\":true}',1,1,'2026-03-10 10:50:12.421476','2026-03-10 11:43:53.000000'),('d6e52777-7693-455b-8df6-36ed7a89df55','CS Issuance Content','Reportorial content of the issuance report of the CS.','section_check','{\"required_sections\":[\"Summary\",\"Assignments\"]}','{\"all_present\":true}',1,1,'2026-03-10 16:40:17.126207','2026-03-10 16:40:17.126207'),('e5366528-16da-4a81-8a4f-9ad8d584a617','CS Issuance Count','Counts the Issuance of Issues in cybersecurity','property_check','{\"mode\":\"number_extraction\",\"field\":\"extracted_text\",\"keywords\":[\"assigned to Ju\",\"assigned to Benj\",\"assigned to Gods\",\"assigned to Milut\"],\"keyword\":\"assigned to Ju\",\"comparison\":\"gte\",\"expected_number\":10,\"expected_numbers\":[10,10,10,10],\"window_chars\":120}','{\"matches_pattern\":true}',1,1,'2026-03-10 16:39:26.744680','2026-03-10 16:39:26.744680'),('metric-001','Introduction Section Check','Verifies the document contains required section headings.','section_check','{\"required_sections\":[\"Introduction\",\"Findings\",\"Recommendations\"]}','{\"all_present\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:05.000000'),('metric-002','Compliance Keyword Presence','Verifies key compliance terms appear in the document body.','keyword_check','{\"keywords\":[\"compliance\",\"regulation\",\"policy\"],\"min_count\":2,\"case_sensitive\":false,\"use_word_boundary\":false}','{\"min_matches\":2}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:09.000000'),('metric-003','Incident Count Extraction','Extracts and validates the reported incident count meets the minimum threshold.','property_check','{\"mode\":\"number_extraction\",\"field\":\"extracted_text\",\"keywords\":[\"x\"],\"keyword\":\"x\",\"comparison\":\"gte\",\"expected_number\":1,\"expected_numbers\":[1],\"window_chars\":120}','{\"matches_pattern\":true}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:32.000000'),('metric-004','Monthly Submission Deadline Check','Validates document submitted before the monthly deadline.','date_check','{\"submission_frequency\":\"monthly\",\"submission_month\":12,\"deadline_day\":5,\"deadline_month_offset\":1,\"max_days_late\":0,\"custom_period_regex\":\"^(\\\\d{4})(\\\\d{2})$\",\"custom_period_year_group\":1,\"custom_period_month_group\":2,\"custom_period_fallback_month\":12}','{\"within_deadline\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:39.000000'),('metric-005','ICT Risk Report Sections','Verifies ICT security assessments contain Executive Summary, Risk Analysis, and Mitigation Plan.','section_check','{\"required_sections\":[\"Executive Summary\",\"Risk Analysis\",\"Mitigation Plan\"]}','{\"all_present\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:43.000000'),('metric-006','ICT Security Keyword Check','Checks that ICT security terms (cybersecurity, vulnerability, patch) appear in the document.','keyword_check','{\"keywords\":[\"cybersecurity\",\"vulnerability\",\"patch\"],\"min_count\":2,\"case_sensitive\":false,\"use_word_boundary\":false}','{\"min_matches\":2}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:47:49.000000'),('metric-007','Vulnerability Count Extraction','Extracts and validates the reported vulnerability count is non-negative.','property_check','{\"mode\":\"number_extraction\",\"field\":\"extracted_text\",\"keywords\":[\"d\"],\"keyword\":\"d\",\"comparison\":\"gte\",\"expected_number\":1,\"expected_numbers\":[1],\"window_chars\":120}','{\"matches_pattern\":true}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:01.000000'),('metric-008','ICT Assessment Deadline Check','Validates ICT security assessments are submitted by the 5th of the month following the report period.','date_check','{\"submission_frequency\":\"monthly\",\"submission_month\":12,\"deadline_day\":5,\"deadline_month_offset\":1,\"max_days_late\":2,\"custom_period_regex\":\"^(\\\\d{4})(\\\\d{2})$\",\"custom_period_year_group\":1,\"custom_period_month_group\":2,\"custom_period_fallback_month\":12}','{\"within_deadline\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:06.000000'),('metric-009','Finance Report Sections','Verifies Finance risk reports contain Budget Summary, Variance Analysis, and Recommendations.','section_check','{\"required_sections\":[\"Budget Summary\",\"Variance Analysis\",\"Recommendations\"]}','{\"all_present\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:11.000000'),('metric-010','Finance Terminology Check','Checks that Finance-specific terms (audit, budget, variance) appear in the document.','keyword_check','{\"keywords\":[\"audit\",\"budget\",\"variance\"],\"min_count\":2,\"case_sensitive\":false,\"use_word_boundary\":false}','{\"min_matches\":2}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:15.000000'),('metric-011','Transaction Count Extraction','Extracts and validates the reported transaction count is at least 1.','property_check','{\"mode\":\"number_extraction\",\"field\":\"extracted_text\",\"keywords\":[\"s\"],\"keyword\":\"s\",\"comparison\":\"lte\",\"expected_number\":1,\"expected_numbers\":[1],\"window_chars\":120}','{\"matches_pattern\":true}',1,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:24.000000'),('metric-012','Finance Report Deadline Check','Validates Finance Risk Reports are submitted by the 7th of the month following the report period.','date_check','{\"submission_frequency\":\"monthly\",\"submission_month\":12,\"deadline_day\":7,\"deadline_month_offset\":1,\"max_days_late\":2,\"custom_period_regex\":\"^(\\\\d{4})(\\\\d{2})$\",\"custom_period_year_group\":1,\"custom_period_month_group\":2,\"custom_period_fallback_month\":12}','{\"within_deadline\":true}',2,1,'2026-03-03 16:50:00.000000','2026-03-10 15:48:29.000000');
