INSERT INTO `mov_artifacts` VALUES ('048e6730-88af-4cda-9f53-0bddd7415161','assessment_plan_year','regional','Year 3 - Integration and Capability Maturity',2028,NULL,NULL,'active','Integrate regional/national requirements, strengthen evidence traceability, and track control effectiveness through KPI-linked review cycles.','{\"year_index\":3}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('07170388-5e58-41fe-8603-857d8723b4a0','assessment_plan_year','regional','Year 1 - Context, Governance, Risk Foundation',2026,NULL,NULL,'active','Map processes by unit, establish governance standards, identify stakeholders and responsibilities, perform baseline technical-operational-compliance risk analysis, map controls to ISO/IEC 27001 and DSWD QMS, then launch initial treatment and pilot validation.','{\"year_index\":1}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('8df7635f-c104-4700-88b4-d3db7ab157de','assessment_schedule_entry','regional','Process Mapping and Governance Setup',2026,1,NULL,'planned','Process Mapping and Governance Setup','{\"owner\":\"ICT Process Owner\",\"due_date\":\"2026-03-31\",\"sample_seed\":true}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('bec9dc7d-d2f7-4049-aab7-2a012b5acbcb','assessment_plan_year','regional','Year 5 - Sustainment and Continuous Improvement',2030,NULL,NULL,'active','Institutionalize continuous improvement, refresh risk methodology, and sustain quality-driven quarterly compliance reporting at maturity state.','{\"year_index\":5}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('cba1d811-344b-4177-aec3-77b8ee5b0116','assessment_schedule_entry','regional','Pilot Audit and Readiness Validation',2026,4,NULL,'planned','Pilot Audit and Readiness Validation','{\"owner\":\"Internal Audit Team\",\"due_date\":\"2026-12-15\",\"sample_seed\":true}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('d2a3b8d8-3ddb-46e4-a3dd-07e8858de92c','assessment_schedule_entry','regional','Risk Treatment and Awareness Rollout',2026,3,NULL,'planned','Risk Treatment and Awareness Rollout','{\"owner\":\"Unit Heads\",\"due_date\":\"2026-09-30\",\"sample_seed\":true}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('e548fec1-a2fa-4d45-9d97-829db4a466f8','assessment_schedule_entry','regional','Risk Analysis and ISMS/QMS Mapping',2026,2,NULL,'planned','Risk Analysis and ISMS/QMS Mapping','{\"owner\":\"Compliance Team\",\"due_date\":\"2026-06-30\",\"sample_seed\":true}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('efbc6609-9d14-4dae-8459-9a0660bd5501','assessment_plan_year','regional','Year 4 - Optimization and Audit Readiness',2029,NULL,NULL,'active','Optimize process bottlenecks, close recurring findings, and ensure complete MoV evidence packs for planned internal and external audits.','{\"year_index\":4}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53'),('f325173b-8425-4d44-b24e-3efdb684bb43','assessment_plan_year','regional','Year 2 - Control Stabilization and Standardization',2027,NULL,NULL,'active','Standardize SOPs from year-1 pilots, expand treatment coverage, improve control consistency, and formalize quarterly management review routines.','{\"year_index\":2}',NULL,'2026-04-16 13:11:53','2026-04-16 13:11:53');
