INSERT INTO `mov_artifacts` VALUES ('259e0eed-8090-4ed8-ab91-019abc5eb39e','assessment_schedule_entry','regional','Pilot Audit and Readiness Validation',2026,4,NULL,'planned','Pilot Audit and Readiness Validation','{\"owner\":\"Internal Audit Team\",\"due_date\":\"2026-12-15\",\"sample_seed\":true}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('2fcbb230-92b0-4b6d-a9f9-468f97f6e076','assessment_plan_year','regional','Year 2 - Control Stabilization and Standardization',2027,NULL,NULL,'active','Standardize SOPs from year-1 pilots, expand treatment coverage, improve control consistency, and formalize quarterly management review routines.','{\"year_index\":2}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('6f8785b1-9250-481d-a99a-8e37de53a54c','assessment_plan_year','regional','Year 4 - Optimization and Audit Readiness',2029,NULL,NULL,'active','Optimize process bottlenecks, close recurring findings, and ensure complete MoV evidence packs for planned internal and external audits.','{\"year_index\":4}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('7acf8c9c-ff6e-4495-9efb-839fddf92b00','assessment_schedule_entry','regional','Process Mapping and Governance Setup',2026,1,NULL,'planned','Process Mapping and Governance Setup','{\"owner\":\"ICT Process Owner\",\"due_date\":\"2026-03-31\",\"sample_seed\":true}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('870d7094-ae3c-4081-b9f0-23c72a0a0da2','assessment_schedule_entry','regional','Risk Analysis and ISMS/QMS Mapping',2026,2,NULL,'planned','Risk Analysis and ISMS/QMS Mapping','{\"owner\":\"Compliance Team\",\"due_date\":\"2026-06-30\",\"sample_seed\":true}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('94be6a2d-760e-41e7-b08b-548cf5fca8ad','assessment_plan_year','regional','Year 1 - Context, Governance, Risk Foundation',2026,NULL,NULL,'active','Map processes by unit, establish governance standards, identify stakeholders and responsibilities, perform baseline technical-operational-compliance risk analysis, map controls to ISO/IEC 27001 and DSWD QMS, then launch initial treatment and pilot validation.','{\"year_index\":1}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('b254e392-302f-4613-9db4-069e983c434a','assessment_plan_year','regional','Year 3 - Integration and Capability Maturity',2028,NULL,NULL,'active','Integrate regional/national requirements, strengthen evidence traceability, and track control effectiveness through KPI-linked review cycles.','{\"year_index\":3}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('bd7bd4cd-e35a-4164-bf3e-102922a41bbb','assessment_schedule_entry','regional','Risk Treatment and Awareness Rollout',2026,3,NULL,'planned','Risk Treatment and Awareness Rollout','{\"owner\":\"Unit Heads\",\"due_date\":\"2026-09-30\",\"sample_seed\":true}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26'),('e3c574ee-2489-4ac7-b629-0deafa1fc2b4','assessment_plan_year','regional','Year 5 - Sustainment and Continuous Improvement',2030,NULL,NULL,'active','Institutionalize continuous improvement, refresh risk methodology, and sustain quality-driven quarterly compliance reporting at maturity state.','{\"year_index\":5}',NULL,'2026-06-03 15:30:26','2026-06-03 15:30:26');
